              "text": "– Đối với các giao dịch ngoại tệ chuyển tiền trong nước sử dụng kênh chuyển tiền quốc tế (SWIFT), chi nhánh có thể áp dụng mức phí chuyển tiền đi nước ngoài qua SWIFT quy định tại mục D. Chuyển tiền đi nước ngoài của Biểu phí, cụ thể là Phí chuyển tiền của VCB (mức phí là 0,2% giá trị giao dịch)."
