              "text": "Phí thu hộ theo bảng kê: Đối với phí Giao dịch thu hộ theo bảng kê, Chi nhánh/TTDVKH thực hiện thu phí trên các chương trình/ hệ thống tác nghiệp hiện hành (T4S/ T4S Plugin) như sau: Chi nhánh/ TTDVKH thực hiện đối soát các giao dịch thu hộ theo bảng kê thành công trên hệ thống VCB CashUp với Khách hàng và thực hiện thu phí theo mức phí quy định tại Biểu phí tại thời điểm thỏa thuận với Khách hàng."
