              "text": "Hướng dẫn thu phí bổ sung/hoàn phí :\n– Trung tâm thanh toán: Thông báo cho Chi nhánh thực hiện giao dịch về việc: (i) Phần phí VCB phải trả Ngân hàng trung gian đó vượt quá mức phí Ngân hàng trung gian đồng ý chi trả; (ii) Ngân hàng trung gian không hỗ trợ dịch vụ “Phí trả đến Ngân hàng Bên thụ hưởng” và Bên thụ hưởng vẫn bị trừ phí; (iii) Phí thực trả Ngân hàng trung gian khác trong trường hợp chuyển tiền JPY qua hơn một Ngân hàng trung gian.\n– Chi nhánh thực hiện: (i) Thông báo với khách hàng các quy định về phí thu bổ sung tại thời điểm thực hiện giao dịch; (ii) Thu phí bổ sung/hoàn phí cho khách hàng trên cơ sở thông báo của Trung tâm thanh toán."
